1	/**
2	 * Instapage Bulk Unpublisher
3	 *
4	 * Reads landing pages from a Google Sheet and unpublishes each one in Instapage.
5	 * Progress is saved to progress.json so the script can resume if interrupted.
6	 *
7	 * Usage: node unpublish.js
8	 */
9	
10	const { chromium } = require('playwright');
11	const https = require('https');
12	const http = require('http');
13	const readline = require('readline');
14	const fs = require('fs');
15	
16	// ─── Config ────────────────────────────────────────────────────────────────────
17	const SHEET_CSV_URL =
18	  'https://docs.google.com/spreadsheets/d/1HZKlucyNgJrgCA55e4tZfUyLhMnHYpkzqMb1kCFSNC4/export?format=csv&gid=0';
19	const PROGRESS_FILE = 'progress.json';
20	const INSTAPAGE_LOGIN = 'https://app.instapage.com/login';
21	const FAILED_FILE = 'failed.json';
22	
23	// ─── Helpers ───────────────────────────────────────────────────────────────────
24	
25	function prompt(question, hidden = false) {
26	  return new Promise(resolve => {
27	    const rl = readline.createInterface({
28	      input: process.stdin,
29	      output: process.stdout,
30	    });
31	    if (hidden) {
32	      // Mask password input
33	      rl.stdoutMuted = true;
34	      rl._writeToOutput = s => {
35	        if (rl.stdoutMuted) rl.output.write('');
36	        else rl.output.write(s);
37	      };
38	    }
39	    rl.question(question, answer => {
40	      if (hidden) process.stdout.write('\n');
41	      rl.close();
42	      resolve(answer);
43	    });
44	  });
45	}
46	
47	function fetchWithRedirects(url, maxRedirects = 5) {
48	  return new Promise((resolve, reject) => {
49	    if (maxRedirects === 0) return reject(new Error('Too many redirects'));
50	    const lib = url.startsWith('https') ? https : http;
51	    lib
52	      .get(url, res => {
53	        const { statusCode, headers } = res;
54	        if ([301, 302, 307, 308].includes(statusCode) && headers.location) {
55	          res.resume();
56	          return fetchWithRedirects(headers.location, maxRedirects - 1)
57	            .then(resolve)
58	            .catch(reject);
59	        }
60	        let data = '';
61	        res.on('data', chunk => (data += chunk));
62	        res.on('end', () => resolve(data));
63	      })
64	      .on('error', reject);
65	  });
66	}
67	
68	function parseCSV(csvText) {
69	  const rows = [];
70	  const lines = csvText.split('\n');
71	  for (const line of lines) {
72	    if (!line.trim()) continue;
73	    const fields = [];
74	    let current = '';
75	    let inQuotes = false;
76	    for (let i = 0; i < line.length; i++) {
77	      const ch = line[i];
78	      if (ch === '"') {
79	        inQuotes = !inQuotes;
80	      } else if (ch === ',' && !inQuotes) {
81	        fields.push(current.trim());
82	        current = '';
83	      } else {
84	        current += ch;
85	      }
86	    }
87	    fields.push(current.trim());
88	    rows.push(fields);
89	  }
90	  return rows;
91	}
92	
93	function loadProgress() {
94	  if (fs.existsSync(PROGRESS_FILE)) {
95	    try {
96	      return JSON.parse(fs.readFileSync(PROGRESS_FILE, 'utf8'));
97	    } catch {
98	      return { completed: [] };
99	    }
100	  }
101	  return { completed: [] };
102	}
103	
104	function saveProgress(progress) {
105	  fs.writeFileSync(PROGRESS_FILE, JSON.stringify(progress, null, 2));
106	}
107	
108	function loadFailed() {
109	  if (fs.existsSync(FAILED_FILE)) {
110	    try {
111	      return JSON.parse(fs.readFileSync(FAILED_FILE, 'utf8'));
112	    } catch {
113	      return [];
114	    }
115	  }
116	  return [];
117	}
118	
119	function saveFailed(failed) {
120	  fs.writeFileSync(FAILED_FILE, JSON.stringify(failed, null, 2));
121	}
122	
123	function log(msg) {
124	  const ts = new Date().toLocaleTimeString();
125	  console.log(`[${ts}] ${msg}`);
126	}
127	
128	// ─── Instapage Actions ─────────────────────────────────────────────────────────
129	
130	async function login(page, email, password) {
131	  log('Navigating to login page...');
132	  await page.goto(INSTAPAGE_LOGIN, { waitUntil: 'networkidle' });
133	
134	  await page.fill('input[type="email"], input[name="email"], input[placeholder*="email" i]', email);
135	  await page.fill(
136	    'input[type="password"], input[name="password"], input[placeholder*="password" i]',
137	    password
138	  );
139	  await page.click(
140	    'button[type="submit"], input[type="submit"], button:has-text("Log in"), button:has-text("Sign in")'
141	  );
142	
143	  // Wait for redirect away from login page
144	  await page.waitForURL(url => !url.includes('/login'), { timeout: 30000 });
145	  log('Login successful.');
146	}
147	
148	async function switchToClient(page, clientName) {
149	  log(`  Switching to client workspace: "${clientName}"`);
150	
151	  // Click the workspace / account switcher in the top-left
152	  const switcherSelectors = [
153	    '[data-testid="workspace-switcher"]',
154	    '[data-testid="account-switcher"]',
155	    '[class*="WorkspaceSwitcher"]',
156	    '[class*="workspace-switcher"]',
157	    '[class*="account-name"]',
158	    '[class*="AccountName"]',
159	    'button[class*="workspace"]',
160	    // Fallback: find a button near the top-left that contains text
161	    'header button',
162	    '.sidebar button',
163	    'nav button:first-child',
164	  ];
165	
166	  let clicked = false;
167	  for (const sel of switcherSelectors) {
168	    try {
169	      const el = page.locator(sel).first();
170	      if (await el.isVisible({ timeout: 2000 })) {
171	        await el.click();
172	        clicked = true;
173	        break;
174	      }
175	    } catch {
176	      // try next selector
177	    }
178	  }
179	
180	  if (!clicked) {
181	    throw new Error('Could not find workspace switcher — selector may have changed.');
182	  }
183	
184	  await page.waitForTimeout(600);
185	
186	  // Type client name in the search box that appears
187	  const searchSelectors = [
188	    'input[placeholder*="search" i]',
189	    'input[placeholder*="filter" i]',
190	    'input[type="search"]',
191	    '[role="combobox"] input',
192	    '[role="listbox"] input',
193	  ];
194	
195	  for (const sel of searchSelectors) {
196	    try {
197	      const el = page.locator(sel).first();
198	      if (await el.isVisible({ timeout: 2000 })) {
199	        await el.fill(clientName);
200	        break;
201	      }
202	    } catch {
203	      // try next
204	    }
205	  }
206	
207	  await page.waitForTimeout(600);
208	
209	  // Click the matching result (exact or partial match)
210	  try {
211	    await page.click(`text="${clientName}"`, { timeout: 5000 });
212	  } catch {
213	    // Try partial match
214	    const option = page.locator(`[role="option"]:has-text("${clientName}")`).first();
215	    if (await option.isVisible({ timeout: 3000 })) {
216	      await option.click();
217	    } else {
218	      throw new Error(`Client "${clientName}" not found in workspace switcher dropdown.`);
219	    }
220	  }
221	
222	  await page.waitForLoadState('networkidle');
223	  log(`  Switched to: "${clientName}"`);
224	}
225	
226	async function findAndOpenPage(page, url) {
227	  log(`  Searching for page: ${url}`);
228	
229	  // Search for the URL in the pages dashboard
230	  const searchSelectors = [
231	    'input[placeholder*="search" i]',
232	    'input[placeholder*="Search" i]',
233	    'input[type="search"]',
234	    '[data-testid="search-input"]',
235	    '[class*="search"] input',
236	  ];
237	
238	  for (const sel of searchSelectors) {
239	    try {
240	      const el = page.locator(sel).first();
241	      if (await el.isVisible({ timeout: 3000 })) {
242	        await el.clear();
243	        await el.fill(url);
244	        break;
245	      }
246	    } catch {
247	      // try next
248	    }
249	  }
250	
251	  await page.waitForTimeout(1000);
252	
253	  // Find the card that shows this URL, then click the bold title above it
254	  // Instapage shows: [Bold Title] on top, [URL] beneath it in a card
255	  try {
256	    // Find the element containing the URL text
257	    const urlEl = page.locator(`text="${url}"`).first();
258	    await urlEl.waitFor({ timeout: 10000 });
259	
260	    // The clickable title is typically a sibling or parent element
261	    // Try going up to the card container and finding the title link
262	    const card = urlEl.locator('xpath=ancestor::*[contains(@class,"page") or contains(@class,"card") or contains(@class,"item")][1]');
263	    const titleLink = card.locator('a, h1, h2, h3, h4, strong, [class*="title"], [class*="name"]').first();
264	
265	    if (await titleLink.isVisible({ timeout: 3000 })) {
266	      await titleLink.click();
267	    } else {
268	      // Fallback: click directly on the URL text area
269	      await urlEl.click();
270	    }
271	  } catch {
272	    throw new Error(`Page with URL "${url}" not found in this workspace.`);
273	  }
274	
275	  // Wait for the flyout / side panel to open
276	  await page.waitForTimeout(1000);
277	  log(`  Page flyout opened.`);
278	}
279	
280	async function unpublishPage(page) {
281	  // Scroll down in the flyout to find "URL Settings"
282	  const flyoutSelectors = [
283	    '[class*="flyout"]',
284	    '[class*="sidebar"]',
285	    '[class*="panel"]',
286	    '[role="dialog"]',
287	    '[class*="drawer"]',
288	  ];
289	
290	  for (const sel of flyoutSelectors) {
291	    try {
292	      const flyout = page.locator(sel).last();
293	      if (await flyout.isVisible({ timeout: 2000 })) {
294	        await flyout.evaluate(el => el.scrollTo(0, el.scrollHeight));
295	        break;
296	      }
297	    } catch {
298	      // try next
299	    }
300	  }
301	
302	  await page.waitForTimeout(500);
303	
304	  // Click "URL Settings"
305	  try {
306	    await page.click('text="URL Settings"', { timeout: 5000 });
307	  } catch {
308	    throw new Error('"URL Settings" button not found in the flyout.');
309	  }
310	
311	  await page.waitForTimeout(800);
312	
313	  // Click "Unpublish"
314	  try {
315	    await page.click('button:has-text("Unpublish"), text="Unpublish"', { timeout: 5000 });
316	  } catch {
317	    throw new Error('"Unpublish" button not found.');
318	  }
319	
320	  await page.waitForTimeout(800);
321	
322	  // Click "Confirm" (or "Yes", "OK")
323	  try {
324	    await page.click(
325	      'button:has-text("Confirm"), button:has-text("Yes"), button:has-text("OK")',
326	      { timeout: 5000 }
327	    );
328	  } catch {
329	    throw new Error('"Confirm" button not found.');
330	  }
331	
332	  await page.waitForTimeout(1000);
333	}
334	
335	// ─── Main ──────────────────────────────────────────────────────────────────────
336	
337	async function main() {
338	  const testMode = process.argv.includes('--test');
339	
340	  console.log('='.repeat(60));
341	  console.log(testMode ? ' Instapage Unpublisher — TEST MODE (1 page)' : ' Instapage Bulk Unpublisher');
342	  console.log('='.repeat(60));
343	
344	  // 1. Fetch and parse the Google Sheet
345	  log('Fetching Google Sheet...');
346	  let csvText;
347	  try {
348	    csvText = await fetchWithRedirects(SHEET_CSV_URL);
349	  } catch (err) {
350	    console.error('Failed to fetch Google Sheet:', err.message);
351	    process.exit(1);
352	  }
353	
354	  const rows = parseCSV(csvText);
355	  // Col A=0 (TRUE/FALSE), Col B=1 (URL), Col C=2 (Title), Col D=3 (Client name)
356	  const toProcess = rows.filter(
357	    row =>
358	      row[0] &&
359	      row[0].toUpperCase() === 'FALSE' &&
360	      row[1] &&
361	      row[3]
362	  );
363	
364	  log(`Total pages to unpublish: ${toProcess.length}`);
365	
366	  // 2. Load progress and filter already-completed
367	  const progress = loadProgress();
368	  const failed = loadFailed();
369	  const remaining = toProcess.filter(row => !progress.completed.includes(row[1]));
370	
371	  log(`Already completed: ${progress.completed.length}`);
372	  log(`Remaining: ${remaining.length}`);
373	
374	  // In test mode, only process the first page
375	  const queue = testMode ? remaining.slice(0, 1) : remaining;
376	  if (testMode) log(`TEST MODE: will only process 1 page → ${queue[0]?.[1]}`);
377	
378	  if (remaining.length === 0) {
379	    console.log('\nAll pages have already been processed. Done!');
380	    return;
381	  }
382	
383	  // 3. Prompt for credentials
384	  console.log('');
385	  const email = await prompt('Instapage email: ');
386	  const password = await prompt('Instapage password: ', true);
387	  console.log('');
388	
389	  // 4. Launch browser (headed so you can watch / intervene)
390	  const browser = await chromium.launch({ headless: false, slowMo: 200 });
391	  const context = await browser.newContext({ viewport: { width: 1400, height: 900 } });
392	  const page = await context.newPage();
393	
394	  try {
395	    // 5. Login
396	    await login(page, email, password);
397	
398	    let currentClient = null;
399	
400	    // 6. Process each page
401	    for (let i = 0; i < queue.length; i++) {
402	      const row = queue[i];
403	      const pageUrl = row[1];
404	      const title = row[2];
405	      const clientName = row[3];
406	
407	      console.log('');
408	      log(`[${i + 1}/${queue.length}] ${title}`);
409	      log(`  URL: ${pageUrl}`);
410	      log(`  Client: ${clientName}`);
411	
412	      try {
413	        // Switch workspace only if client changed
414	        if (clientName !== currentClient) {
415	          await page.goto('https://app.instapage.com/dashboard2', { waitUntil: 'networkidle' });
416	          await switchToClient(page, clientName);
417	          currentClient = clientName;
418	        }
419	
420	        await findAndOpenPage(page, pageUrl);
421	        await unpublishPage(page);
422	
423	        log(`  ✓ UNPUBLISHED`);
424	        progress.completed.push(pageUrl);
425	        saveProgress(progress);
426	
427	      } catch (err) {
428	        log(`  ✗ FAILED: ${err.message}`);
429	        failed.push({ url: pageUrl, title, clientName, error: err.message });
430	        saveFailed(failed);
431	        currentClient = null; // Reset so next iteration re-navigates
432	      }
433	    }
434	
435	  } finally {
436	    await browser.close();
437	  }
438	
439	  // 7. Summary
440	  console.log('');
441	  console.log('='.repeat(60));
442	  console.log(` Done!`);
443	  console.log(`  Completed: ${progress.completed.length}`);
444	  console.log(`  Failed:    ${failed.length}`);
445	  if (failed.length > 0) {
446	    console.log(`\n  Failed pages saved to: ${FAILED_FILE}`);
447	    console.log('  Review and re-run the script to retry them,');
448	    console.log('  or handle them manually.');
449	  }
450	  console.log('='.repeat(60));
451	}
452	
453	main().catch(err => {
454	  console.error('\nFatal error:', err.message);
455	  process.exit(1);
456	});
